  for (let x = 11; x <= 30; x++) {
    if (x >= 18 && x <= 20) continue;
    if (x === 17) { for (let y = 2; y <= 4; y++) put(x, y, 8, PAVING); continue; }
    for (let y = 2; y <= 4; y++) {
      if (x >= 22 && x <= 30 && y === 4) continue;
      put(x, y, 8, STUCCO);
    }
  }

