  for (let z = 9; z <= 24; z++) for (let y = 2; y <= 4; y++) {
    if (z === 10 && y <= 3) continue;
    if (z >= 14 && z <= 16 && y >= 3) continue;
    put(10, y, z, STUCCO);
  }

